-- >>> 20261104000100_planning_wellbeing_tables.sql
-- =============================================================================
-- AVEN Stage 5 — Migration 11: Planning and Wellbeing tables
--
-- Same rules as finance (docs/DATABASE.md):
--   * ids are generated by the client (so records can be created offline);
--   * users may only READ these tables — every write goes through
--     public.apply_life_mutation() (next migration): idempotent receipts,
--     optimistic versions, ownership checks, wellbeing consent;
--   * triggers re-check cross-table ownership whatever the write path.
--
-- Wellbeing records are sensitive. They can only be written while the user
-- has granted the `wellbeing_data` consent (checked in apply_life_mutation),
-- are visible only to their owner (RLS), and are never sent to Walrus Memory
-- without the separate `memory_wellbeing` consent.
-- =============================================================================

-- Generic guard: a referenced row (TG_ARGV[0] table, TG_ARGV[1] column) must
-- belong to the same user as the new row.
create or replace function private.guard_owned_ref()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_ok boolean;
  v_ref uuid;
begin
  execute format('select ($1).%I', tg_argv[1]) into v_ref using new;
  if v_ref is null then
    return new;
  end if;
  execute format('select exists (select 1 from public.%I where id = $1 and user_id = $2)', tg_argv[0])
    into v_ok using v_ref, new.user_id;
  if not v_ok then
    raise exception 'Referenced record not found' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace function private.guard_user_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.user_id <> old.user_id or new.id <> old.id then
    raise exception 'Ownership cannot change' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: task categories and tasks
-- -----------------------------------------------------------------------------
create table public.task_categories (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 40),
  archived_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index task_categories_user_idx on public.task_categories (user_id);
create unique index task_categories_active_name_uniq
  on public.task_categories (user_id, lower(btrim(name))) where archived_at is null;

create table public.tasks (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 1 and 200),
  description text check (description is null or char_length(description) <= 2000),
  status text not null default 'not_started'
    check (status in ('not_started', 'in_progress', 'completed', 'cancelled')),
  priority text not null default 'medium' check (priority in ('low', 'medium', 'high')),
  category_id uuid references public.task_categories (id) on delete set null,
  -- Due date/time are LOCAL to the user's time zone; remind_at is an exact instant.
  due_on date,
  due_time time,
  remind_at timestamptz,
  completed_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (due_time is null or due_on is not null),
  check ((status = 'completed') = (completed_at is not null))
);
create index tasks_user_status_idx on public.tasks (user_id, status, due_on);
create index tasks_user_remind_idx on public.tasks (user_id, remind_at) where remind_at is not null;

-- completed_at follows the status, so it can never be forged or forgotten.
create or replace function private.task_completion()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'completed' then
    new.completed_at := case
      when tg_op = 'UPDATE' and old.status = 'completed' then old.completed_at
      else now() end;
  else
    new.completed_at := null;
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: calendar events (recurrence is expanded on read, never stored as
-- copies — so recurring events cannot produce duplicate records)
-- -----------------------------------------------------------------------------
create table public.calendar_events (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 1 and 200),
  description text check (description is null or char_length(description) <= 2000),
  category text not null default 'personal'
    check (category in ('personal', 'work', 'health', 'finance', 'social', 'learning', 'other')),
  all_day boolean not null default false,
  -- Timed events: exact instants.
  starts_at timestamptz,
  ends_at timestamptz,
  -- All-day events: local dates (inclusive).
  start_date date,
  end_date date,
  -- The zone the event's wall-clock times (and recurrence) belong to.
  time_zone text not null check (char_length(time_zone) between 1 and 64),
  recurrence text check (recurrence in ('daily', 'weekly', 'monthly', 'yearly')),
  recurrence_interval smallint not null default 1 check (recurrence_interval between 1 and 99),
  -- 0 = Sunday … 6 = Saturday (weekly recurrence only).
  recurrence_weekdays smallint[] check (
    recurrence_weekdays is null
    or (cardinality(recurrence_weekdays) between 1 and 7 and recurrence_weekdays <@ array[0,1,2,3,4,5,6]::smallint[])
  ),
  recurrence_until date,
  reminder_minutes integer check (reminder_minutes is null or reminder_minutes between 0 and 10080),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (
    (all_day and start_date is not null and end_date is not null and end_date >= start_date
      and end_date - start_date <= 31 and starts_at is null and ends_at is null)
    or (not all_day and starts_at is not null and ends_at is not null and ends_at >= starts_at
      and ends_at - starts_at <= interval '14 days' and start_date is null and end_date is null)
  ),
  check (recurrence is not null or (recurrence_weekdays is null and recurrence_until is null)),
  check (recurrence_weekdays is null or recurrence = 'weekly')
);
create index calendar_events_user_start_idx on public.calendar_events (user_id, starts_at);
create index calendar_events_user_date_idx on public.calendar_events (user_id, start_date);
create index calendar_events_user_recurring_idx on public.calendar_events (user_id) where recurrence is not null;

create trigger calendar_events_validate_time_zone
  before insert or update of time_zone on public.calendar_events
  for each row execute function private.validate_time_zone();

-- One exception per occurrence of a recurring event: cancelled, or moved/renamed.
create table public.calendar_event_exceptions (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  event_id uuid not null references public.calendar_events (id) on delete cascade,
  -- The LOCAL date the occurrence would originally have started on.
  occurrence_date date not null,
  cancelled boolean not null default true,
  starts_at timestamptz,
  ends_at timestamptz,
  title text check (title is null or char_length(btrim(title)) between 1 and 200),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint calendar_event_exceptions_occurrence_uniq unique (event_id, occurrence_date),
  check (cancelled or (starts_at is not null and ends_at is not null and ends_at >= starts_at))
);
create index calendar_event_exceptions_user_idx on public.calendar_event_exceptions (user_id);

create or replace function private.guard_event_exception()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.calendar_events e
    where e.id = new.event_id and e.user_id = new.user_id and e.recurrence is not null
  ) then
    raise exception 'Recurring event not found' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: habits and dated check-ins
-- -----------------------------------------------------------------------------
create table public.habits (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  description text check (description is null or char_length(description) <= 500),
  category text not null default 'routine' check (
    category in ('health', 'fitness', 'mind', 'learning', 'finance', 'sleep', 'hydration', 'routine', 'other')
  ),
  frequency text not null default 'daily' check (frequency in ('daily', 'specific_days')),
  weekdays smallint[] check (
    weekdays is null
    or (cardinality(weekdays) between 1 and 7 and weekdays <@ array[0,1,2,3,4,5,6]::smallint[])
  ),
  start_on date not null,
  end_on date,
  reminder_time time,
  time_zone text not null check (char_length(time_zone) between 1 and 64),
  archived_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_on is null or end_on >= start_on),
  check ((frequency = 'specific_days') = (weekdays is not null))
);
create index habits_user_idx on public.habits (user_id) where archived_at is null;

create trigger habits_validate_time_zone
  before insert or update of time_zone on public.habits
  for each row execute function private.validate_time_zone();

create table public.habit_check_ins (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  habit_id uuid not null references public.habits (id) on delete cascade,
  on_date date not null,
  status text not null default 'done' check (status in ('done', 'skipped')),
  note text check (note is null or char_length(note) <= 300),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint habit_check_ins_day_uniq unique (habit_id, on_date)
);
create index habit_check_ins_user_date_idx on public.habit_check_ins (user_id, on_date);

-- A check-in must be for the user's own habit, inside its active period, and
-- not in the future (in the habit's time zone).
create or replace function private.guard_habit_check_in()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_habit public.habits%rowtype;
begin
  select * into v_habit from public.habits h where h.id = new.habit_id and h.user_id = new.user_id;
  if not found then
    raise exception 'Habit not found' using errcode = '42501';
  end if;
  if new.on_date < v_habit.start_on or (v_habit.end_on is not null and new.on_date > v_habit.end_on) then
    raise exception 'That date is outside this habit''s schedule' using errcode = '22023';
  end if;
  if new.on_date > (now() at time zone v_habit.time_zone)::date then
    raise exception 'You can''t check in for a future day' using errcode = '22023';
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Planning: private daily and weekly reviews
-- -----------------------------------------------------------------------------
create table public.reviews (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('daily', 'weekly')),
  -- Daily: the day. Weekly: the first day of the week.
  period_start date not null,
  highlights text check (highlights is null or char_length(highlights) <= 4000),
  missed text check (missed is null or char_length(missed) <= 4000),
  next_focus text check (next_focus is null or char_length(next_focus) <= 4000),
  notes text check (notes is null or char_length(notes) <= 8000),
  rating smallint check (rating is null or rating between 1 and 5),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint reviews_period_uniq unique (user_id, kind, period_start)
);

create table public.planning_preferences (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  daily_review_enabled boolean not null default true,
  daily_review_time time not null default '20:30',
  weekly_review_enabled boolean not null default true,
  weekly_review_day smallint not null default 0 check (weekly_review_day between 0 and 6),
  weekly_review_time time not null default '18:00',
  -- Include a "review your finances" step (links to Money; no finance data is copied).
  weekly_finance_review boolean not null default true,
  updated_at timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Wellbeing
-- -----------------------------------------------------------------------------
create table public.wellbeing_preferences (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  water_unit text not null default 'ml' check (water_unit in ('ml', 'l', 'fl_oz')),
  water_target_ml integer not null default 2000 check (water_target_ml between 250 and 10000),
  distance_unit text not null default 'km' check (distance_unit in ('km', 'mi')),
  sleep_target_minutes smallint not null default 480 check (sleep_target_minutes between 180 and 900),
  updated_at timestamptz not null default now()
);

create table public.sleep_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  -- Exact instants, so overnight sleep and daylight-saving changes are handled
  -- by subtraction; wake_date is the user's LOCAL date of waking.
  slept_at timestamptz not null,
  woke_at timestamptz not null,
  wake_date date not null,
  duration_minutes integer generated always as ((extract(epoch from (woke_at - slept_at)) / 60)::integer) stored,
  quality smallint check (quality is null or quality between 1 and 5),
  note text check (note is null or char_length(note) <= 500),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (woke_at > slept_at and woke_at - slept_at <= interval '20 hours')
);
create index sleep_logs_user_date_idx on public.sleep_logs (user_id, wake_date);

create table public.water_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  -- Always stored in millilitres; shown in the user's chosen unit.
  amount_ml integer not null check (amount_ml between 1 and 5000),
  logged_at timestamptz not null,
  local_date date not null,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index water_logs_user_date_idx on public.water_logs (user_id, local_date);

create table public.meal_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  meal_type text not null check (meal_type in ('breakfast', 'lunch', 'dinner', 'snack')),
  description text not null check (char_length(btrim(description)) between 1 and 300),
  eaten_at timestamptz not null,
  local_date date not null,
  note text check (note is null or char_length(note) <= 500),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index meal_logs_user_date_idx on public.meal_logs (user_id, local_date);

create table public.activity_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  activity_type text not null check (
    activity_type in ('walking', 'running', 'cycling', 'gym', 'swimming', 'sports', 'home_workout', 'other')
  ),
  duration_minutes integer not null check (duration_minutes between 1 and 1440),
  -- Always stored in metres; shown in km or miles.
  distance_m integer check (distance_m is null or distance_m between 0 and 1000000),
  intensity text check (intensity is null or intensity in ('light', 'moderate', 'vigorous')),
  on_date date not null,
  note text check (note is null or char_length(note) <= 500),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index activity_logs_user_date_idx on public.activity_logs (user_id, on_date);

-- Mood, energy and stress check-ins. Pulse Check entries are stored here too
-- (source = 'pulse_check'), so there is exactly one place for how you feel.
create table public.mood_logs (
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  logged_at timestamptz not null,
  local_date date not null,
  mood smallint check (mood is null or mood between 1 and 5),
  energy smallint check (energy is null or energy between 1 and 5),
  stress smallint check (stress is null or stress between 1 and 5),
  sleep_rating smallint check (sleep_rating is null or sleep_rating between 1 and 5),
  day_rating smallint check (day_rating is null or day_rating between 1 and 5),
  note text check (note is null or char_length(note) <= 1000),
  source text not null default 'wellbeing' check (source in ('wellbeing', 'pulse_check')),
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (num_nonnulls(mood, energy, stress, sleep_rating, day_rating, note) > 0)
);
create index mood_logs_user_date_idx on public.mood_logs (user_id, local_date);

-- -----------------------------------------------------------------------------
-- Shared triggers and access for every record table above
-- -----------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'task_categories', 'tasks', 'calendar_events', 'calendar_event_exceptions', 'habits',
    'habit_check_ins', 'reviews', 'sleep_logs', 'water_logs', 'meal_logs', 'activity_logs', 'mood_logs'
  ] loop
    execute format('create trigger %I before update on public.%I for each row execute function private.bump_version()', t || '_bump_version', t);
    execute format('create trigger %I before update on public.%I for each row execute function private.guard_user_immutable()', t || '_guard_owner', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
    execute format('grant select on table public.%I to authenticated', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      'Users can read their own ' || replace(t, '_', ' '), t);
    execute format('create index if not exists %I on public.%I (user_id)', t || '_owner_idx', t);
  end loop;
end;
$$;

create trigger tasks_completion before insert or update of status on public.tasks
  for each row execute function private.task_completion();
create trigger tasks_category_owner before insert or update of category_id on public.tasks
  for each row execute function private.guard_owned_ref('task_categories', 'category_id');
create trigger calendar_event_exceptions_guard before insert or update of event_id on public.calendar_event_exceptions
  for each row execute function private.guard_event_exception();
create trigger habit_check_ins_guard before insert or update of habit_id, on_date on public.habit_check_ins
  for each row execute function private.guard_habit_check_in();

-- Preferences: one row per user, created on first save; owner read/insert/update.
do $$
declare
  t text;
begin
  foreach t in array array['planning_preferences', 'wellbeing_preferences'] loop
    execute format('create trigger %I before update on public.%I for each row execute function private.set_updated_at()', t || '_set_updated_at', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
    execute format('grant select, insert, update on table public.%I to authenticated', t);
    execute format('create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))', 'Users can read their own ' || replace(t, '_', ' '), t);
    execute format('create policy %I on public.%I for insert to authenticated with check (user_id = (select auth.uid()))', 'Users can create their own ' || replace(t, '_', ' '), t);
    execute format('create policy %I on public.%I for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', 'Users can update their own ' || replace(t, '_', ' '), t);
  end loop;
end;
$$;

